3	import { useEffect, useState } from 'react';
4	import styles from './hero.module.css';
5	
6	const PHRASES = ['Ownership Driven', 'Without Hiring', 'On Demand'] as const;
7	
8	/**
9	 * Typewriter — SSR-safe phrase cycler.
10	 *
11	 * Hydration contract:
12	 *   • Server renders index=0 ("Ownership Driven"), no fade class.
13	 *   • First client render also renders index=0 with no fade class.
14	 *   • DOM bytes match → no hydration mismatch.
15	 *   • After mount, useEffect kicks the interval and adds the fade class on swap.
16	 */
17	export function Typewriter() {
18	  const [index, setIndex] = useState(0);
19	  const [animate, setAnimate] = useState(false);
20	
21	  useEffect(() => {
22	    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
23	    if (mq.matches) return;
24	    setAnimate(true);
25	    const id = setInterval(() => {
26	      setIndex((p) => (p + 1) % PHRASES.length);
27	    }, 2400);
28	    return () => clearInterval(id);
29	  }, []);
30	
31	  return (
32	    <span
33	      aria-live="polite"
34	      aria-atomic="true"
35	      className={styles['typewriterContainer']}
36	    >
37	      <span
38	        key={index}
39	        className={`${styles['animate-span']} ${styles['typewriterWord']}${
40	          animate ? ` ${styles['typewriterFade']}` : ''
41	        }`}
42	      >
43	        {PHRASES[index]}
44	      </span>
45	    </span>
46	  );
47	}
