79	  const handleScroll = useCallback(() => {
80	    const el = trackRef.current;
81	    if (!el) return;
82	    const perPage = getSlidesPerPage();
83	    const dots = Math.ceil(BENEFITS.length / perPage);
84	    const scrollRatio = el.scrollLeft / (el.scrollWidth - el.clientWidth);
85	    const dot = Math.round(scrollRatio * (dots - 1));
